import{_ as t,a as r,o as a,a4 as n}from"./chunks/framework.-FZumj2l.js";const p=JSON.parse(`{"title":"Cancel a Return","description":"","frontmatter":{"outline":false,"examples":[{"id":"cancel-return","title":"Cancel a Return","description":"Cancel the authenticated customer's own return (RMA) request.","query":"mutation CancelCustomerReturn($id: ID!) {\\n  cancelCustomerReturn(input: { id: $id }) {\\n    customerReturn {\\n      _id\\n      orderId\\n      orderIncrementId\\n      statusId\\n      statusTitle\\n      statusColor\\n      canClose\\n      canReopen\\n      isExpired\\n      messagesCount\\n      updatedAt\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"id\\": \\"/api/shop/returns/12\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"cancelCustomerReturn\\": {\\n      \\"customerReturn\\": {\\n        \\"_id\\": 12,\\n        \\"orderId\\": 45,\\n        \\"orderIncrementId\\": \\"000000045\\",\\n        \\"statusId\\": 4,\\n        \\"statusTitle\\": \\"Canceled\\",\\n        \\"statusColor\\": \\"#F04438\\",\\n        \\"canClose\\": false,\\n        \\"canReopen\\": true,\\n        \\"isExpired\\": false,\\n        \\"messagesCount\\": 2,\\n        \\"updatedAt\\": \\"2026-07-20T11:00:00+00:00\\"\\n      }\\n    }\\n  }\\n}\\n","commonErrors":[{"error":"already canceled","cause":"The return is already in a canceled state","solution":"A return can only be canceled once"},{"error":"UNAUTHENTICATED","cause":"Missing or invalid customer Bearer token","solution":"Log in and provide a valid customer authentication token"},{"error":"NOT_FOUND","cause":"The return does not exist or is not owned by the authenticated customer","solution":"Only return IDs belonging to the logged-in customer can be canceled"}]}]},"headers":[],"relativePath":"api/graphql-api/shop/returns/mutations/cancel-return.md","filePath":"api/graphql-api/shop/returns/mutations/cancel-return.md","lastUpdated":1784902076000}`),d={name:"api/graphql-api/shop/returns/mutations/cancel-return.md"};function o(s,e,c,u,i,l){return a(),r("div",null,e[0]||(e[0]=[n('<h1 id="cancel-a-return" tabindex="-1">Cancel a Return <a class="header-anchor" href="#cancel-a-return" aria-label="Permalink to &quot;Cancel a Return&quot;">​</a></h1><h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><p>The <code>cancelCustomerReturn</code> mutation cancels the customer&#39;s own return (RMA) request, unless it is already canceled. The result carries the updated return with its new status and action flags.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>This mutation requires an authenticated customer — send the storefront key and a customer Bearer token. See the <a href="/api/graphql-api/authentication.html">Authentication</a> page.</p><h2 id="input-fields" tabindex="-1">Input Fields <a class="header-anchor" href="#input-fields" aria-label="Permalink to &quot;Input Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>ID!</code></td><td>✅ Yes</td><td>The return IRI, e.g. <code>/api/shop/returns/12</code>.</td></tr></tbody></table><h2 id="possible-returns" tabindex="-1">Possible Returns <a class="header-anchor" href="#possible-returns" aria-label="Permalink to &quot;Possible Returns&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>customerReturn._id</code></td><td><code>Int!</code></td><td>Numeric return ID.</td></tr><tr><td><code>customerReturn.orderId</code></td><td><code>Int!</code></td><td>Id of the order the item belongs to.</td></tr><tr><td><code>customerReturn.orderIncrementId</code></td><td><code>String!</code></td><td>Human-readable order number.</td></tr><tr><td><code>customerReturn.statusId</code></td><td><code>Int!</code></td><td>Numeric status id after the cancel.</td></tr><tr><td><code>customerReturn.statusTitle</code></td><td><code>String!</code></td><td>Status label, e.g. <code>Canceled</code>.</td></tr><tr><td><code>customerReturn.statusColor</code></td><td><code>String!</code></td><td>Hex color for the status badge.</td></tr><tr><td><code>customerReturn.canClose</code></td><td><code>Boolean</code></td><td>Whether the return can be closed.</td></tr><tr><td><code>customerReturn.canReopen</code></td><td><code>Boolean</code></td><td>Whether the return can be reopened.</td></tr><tr><td><code>customerReturn.isExpired</code></td><td><code>Boolean</code></td><td>Whether the return is past its action window.</td></tr><tr><td><code>customerReturn.messagesCount</code></td><td><code>Int!</code></td><td>Number of conversation messages on the return.</td></tr><tr><td><code>customerReturn.updatedAt</code></td><td><code>DateTime!</code></td><td>Return last update timestamp.</td></tr></tbody></table><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/graphql-api/shop/returns/mutations/reopen-return.html">Reopen a Return</a></li><li><a href="/api/graphql-api/shop/returns/queries/view-return.html">View Return</a></li><li><a href="/api/graphql-api/shop/returns/">Returns Overview</a></li></ul>',11)]))}const m=t(d,[["render",o]]);export{p as __pageData,m as default};
